package com.lolfm.champion;import static org.assertj.core.api.Assertions.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.lolfm.simulator.*;import org.junit.jupiter.api.Test;
class ChampionPowerProfileEvaluatorTest{final ChampionPowerProfileCatalog c=new ChampionPowerProfileCatalog(new ObjectMapper(),new ChampionCatalog(new ObjectMapper()));final ChampionPowerProfileEvaluator e=new ChampionPowerProfileEvaluator(c);double v(String id,int level,ItemProgressStage item,ProgressionCombatContext context){return e.evaluate(new ChampionId(id),level,item,context).clampedPlayerChampionPower();}
 @Test void formulaSeparatesLevelItemContextAndClamps(){var x=e.evaluate(new ChampionId("renekton"),6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.LANE_COMBAT);assertThat(x.levelModifier()).isEqualTo(.28);assertThat(x.itemModifier()).isEqualTo(.18);assertThat(x.contextModifier()).isEqualTo(.22);assertThat(x.rawPlayerChampionPower()).isEqualTo(.68);assertThat(x.playerClampApplied()).isFalse();}
 @Test void focusedProfileDirectionsHold(){assertThat(v("renekton",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.LANE_COMBAT)).isGreaterThan(v("jax",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.LANE_COMBAT));assertThat(v("jax",18,ItemProgressStage.FOURTH_CORE,ProgressionCombatContext.LATE_GAME_SIEGE)).isGreaterThan(v("renekton",18,ItemProgressStage.FOURTH_CORE,ProgressionCombatContext.LATE_GAME_SIEGE));assertThat(v("lee-sin",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.JUNGLE_GANK)).isGreaterThan(v("viego",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.JUNGLE_GANK));assertThat(v("viego",16,ItemProgressStage.THIRD_CORE,ProgressionCombatContext.TEAMFIGHT)).isGreaterThan(v("lee-sin",16,ItemProgressStage.THIRD_CORE,ProgressionCombatContext.TEAMFIGHT));assertThat(v("leblanc",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.ROAM)).isGreaterThan(v("azir",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.ROAM));assertThat(v("azir",16,ItemProgressStage.THIRD_CORE,ProgressionCombatContext.TEAMFIGHT)).isGreaterThan(v("leblanc",16,ItemProgressStage.THIRD_CORE,ProgressionCombatContext.TEAMFIGHT));}
 @Test void adcAndSupportTimingDirectionsHold(){assertThat(v("lucian",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.LANE_COMBAT)).isGreaterThan(v("jinx",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.LANE_COMBAT));assertThat(v("jinx",18,ItemProgressStage.FOURTH_CORE,ProgressionCombatContext.TEAMFIGHT)).isGreaterThan(v("lucian",18,ItemProgressStage.FOURTH_CORE,ProgressionCombatContext.TEAMFIGHT));assertThat(v("nautilus",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.ROAM)).isGreaterThan(v("lulu",6,ItemProgressStage.FIRST_CORE,ProgressionCombatContext.ROAM));assertThat(v("lulu",16,ItemProgressStage.THIRD_CORE,ProgressionCombatContext.BASE_DEFENSE)).isGreaterThan(v("nautilus",16,ItemProgressStage.THIRD_CORE,ProgressionCombatContext.BASE_DEFENSE));}
}
